function load(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}function save(k,v){localStorage.setItem(k,JSON.stringify(v))}function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function courseCard(c){let prog=state.progress[c.id]||0;return `<article class="course-card"><a class="course-art ${c.color}" href="#course/${c.id}"><span class="course-tag">${c.tag}</span><span class="microbe-art">${c.icon}</span><span class="art-label">${c.category}</span></a><div class="course-body"><div class="course-meta"><span>${c.level}</span><span>·</span><span>${c.duration}</span></div><a href="#course/${c.id}" class="course-title">${c.title}</a><p>${c.desc}</p><div class="course-teacher"><span class="teacher-avatar">${c.instructor.split(' ').slice(-1)[0][0]}</span><span>${c.instructor}</span></div><div class="course-bottom"><span>▧ ${c.lessons} lessons</span><button class="save-course ${state.bookmarks.includes(c.id)?'saved':''}" data-bookmark="${c.id}" aria-label="Bookmark course">${state.bookmarks.includes(c.id)?'♥':'♡'}</button></div>${state.enrolled.includes(c.id)?`<div class="progress-line"><i style="width:${prog}%"></i></div>`:''}</div></article>`}
function header(kicker,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow"><span class="eyebrow-dot"></span>${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function home(){let first=courseData.find(c=>c.id==='cell');return `<section class="welcome-banner"><div class="banner-copy"><span class="eyebrow"><span class="eyebrow-dot"></span>A SMALL WORLD. A BIGGER PICTURE.</span><h1>Discover the<br><em>science of life.</em></h1><p>Learn microbiology with free, thoughtfully structured courses, research resources and a community that shares your curiosity.</p><div class="banner-actions"><a class="btn btn-primary" href="#courses">Explore courses <span>→</span></a><a class="banner-link" href="#about">How AM Educare works <span>↗</span></a></div><div class="banner-stats"><div><b>100%</b><small>FREE TO LEARN</small></div><i></i><div><b>10</b><small>SUBJECT AREAS</small></div><i></i><div><b>∞</b><small>QUESTIONS WELCOME</small></div></div></div><div class="banner-visual" aria-label="Illustration of a microscopic organism"><div class="visual-grid"></div><span class="visual-cross">+</span><div class="cell-orbit orbit-a"></div><div class="cell-orbit orbit-b"></div><div class="cell-body"><span class="cell-core"></span><i class="cell-dot d1"></i><i class="cell-dot d2"></i><i class="cell-dot d3"></i><i class="cell-dot d4"></i></div><div class="visual-note note-a">FIG. 01 <span>·</span> BACTERIAL CELL</div><div class="visual-note note-b"><span class="live-dot"></span> THE MICROSCOPIC WORLD, OPENED UP</div></div></section><section class="learning-strip"><span>CURIOUS MINDS START HERE</span><div>${['Bacteriology','Virology','Immunology','Microbial ecology','Laboratory skills'].map(x=>`<b>${x}<i>✳</i></b>`).join('')}</div></section><section class="section-block"><div class="section-heading"><div><div class="eyebrow">A GOOD PLACE TO BEGIN</div><h2>Learning, one <em>discovery</em><br>at a time.</h2></div><a class="arrow-link" href="#courses">Browse all courses <span>↗</span></a></div><div class="course-grid">${courseData.slice(0,3).map(courseCard).join('')}</div></section><section class="pathway"><div class="path-copy"><div class="eyebrow">YOUR NEXT CHAPTER</div><h2>Small steps.<br><em>Stronger foundations.</em></h2><p>Whether you're new to the subject or returning to the lab, find a path that makes the science click.</p><a class="btn btn-dark" href="#dashboard">See your learning path <span>→</span></a></div><div class="path-steps">${[['01','Start with the fundamentals','Get comfortable with cells, diversity and the language of microbiology.'],['02','Follow your curiosity','Explore a specialism, from immunity to the microbial world outside.'],['03','Put knowledge to work','Build your scientific confidence with quizzes, resources and community.']].map(([n,t,d])=>`<div class="path-step"><span>${n}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}</div></section><section class="section-block feature-block"><div class="section-heading"><div><div class="eyebrow">BEYOND THE LECTURE</div><h2>Made for the <em>way you learn.</em></h2></div><a class="arrow-link" href="#resources">Visit the study library <span>↗</span></a></div><div class="feature-grid"><a class="feature-card feature-library" href="#resources"><span class="feature-icon">▧</span><div><span class="eyebrow">THE STUDY LIBRARY</span><h3>Clear notes.<br>Curated carefully.</h3><p>A growing collection of glossaries, revision guides and reference materials.</p></div><span class="feature-arrow">↗</span></a><a class="feature-card feature-quiz" href="#quiz"><span class="feature-icon">✓</span><div><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><h3>A little practice<br>goes a long way.</h3><p>Take a quick quiz and find out what has started to stick.</p></div><span class="feature-arrow">↗</span></a><a class="feature-card feature-community" href="#community"><span class="feature-icon">◉</span><div><span class="eyebrow">BETTER, TOGETHER</span><h3>Science is a<br>conversation.</h3><p>Ask a question, share an idea and meet curious minds.</p></div><span class="feature-arrow">↗</span></a></div></section><section class="closing-cta"><div><span class="eyebrow">THE INVITATION IS OPEN</span><h2>Ready to meet the<br><em>world you can't see?</em></h2></div><a class="btn btn-primary" href="#courses">Find your first course <span>→</span></a><div class="cta-microbe">✳</div></section>`}
function courseList(){let list=courseData.filter(c=>(state.category==='All subjects'||c.category===state.category)&&(state.level==='All levels'||c.level===state.level)&&`${c.title} ${c.desc} ${c.category}`.toLowerCase().includes(state.query.toLowerCase()));return `${header('THE COURSE CATALOGUE','Follow your <em>curiosity.</em>','Every course is free. Start at the beginning, go deeper, and learn at your own pace.',`<a class="btn btn-primary" href="#dashboard">My learning <span>→</span></a>`)}<div class="filter-bar"><label class="search-box"><span>⌕</span><input id="courseSearch" value="${esc(state.query)}" placeholder="Search courses, topics, skills…"></label><select id="categoryFilter"><option>All subjects</option>${cats.map(c=>`<option ${state.category===c?'selected':''}>${c}</option>`).join('')}</select><select id="levelFilter"><option>All levels</option>${['Beginner','Intermediate','Advanced'].map(c=>`<option ${state.level===c?'selected':''}>${c}</option>`).join('')}</select><span class="result-count">${list.length} courses</span></div><div class="category-pills">${cats.map((c,i)=>`<button class="category-pill ${state.category===c?'active':''}" data-cat="${c}"><span>${['◉','▤','∿','✚','✳','⌘','⚗','❋','⌬','⌕'][i]}</span>${c}</button>`).join('')}</div><div class="course-grid catalog-grid">${list.length?list.map(courseCard).join(''):'<div class="empty-state"><span>⌕</span><h3>No courses found yet</h3><p>Try a different search or subject.</p></div>'}</div><div class="note-banner"><span>✳</span><p><b>Learning note</b> Our courses are for education and scientific understanding. Practical laboratory work should always be guided by qualified supervisors and institutional safety procedures.</p></div>`}
function detail(id){let c=courseData.find(x=>x.id===id);if(!c)return `<div class="empty-state"><h3>Course not found</h3><a href="#courses">Back to courses</a></div>`;let joined=state.enrolled.includes(id),prog=state.progress[id]||0;return `<a class="back-link" href="#courses">← All courses</a><section class="course-detail-hero"><div><span class="eyebrow">${c.category.toUpperCase()} · ${c.level.toUpperCase()}</span><h1>${c.title}</h1><p>${c.desc}</p><div class="detail-teacher"><span class="teacher-avatar">${c.instructor.split(' ').slice(-1)[0][0]}</span><span>Created by <b>${c.instructor}</b></span></div><div class="detail-facts"><span>◷ ${c.duration}</span><span>▤ ${c.lessons} lessons</span><span>✳ Certificate of completion</span></div>${joined?`<a class="btn btn-primary" href="#lesson/${id}">Continue learning <span>→</span></a><span class="detail-progress">${prog}% complete</span>`:`<button class="btn btn-primary" data-enroll="${id}">Enroll for free <span>→</span></button>`}</div><div class="detail-art ${c.color}"><div class="cell-body large-cell"><span class="cell-core"></span><i class="cell-dot d1"></i><i class="cell-dot d2"></i><i class="cell-dot d3"></i></div><span class="art-label">${c.tag}</span></div></section><div class="detail-layout"><section><div class="content-panel"><span class="eyebrow">WHAT YOU'LL EXPLORE</span><h2>Learning objectives</h2><ul class="objective-list"><li>Describe key concepts and vocabulary in ${c.category.toLowerCase()}.</li><li>Connect foundational theory to current scientific understanding.</li><li>Interpret examples and evidence with a critical scientific lens.</li><li>Build confidence through guided lessons and knowledge checks.</li></ul></div><div class="content-panel syllabus"><span class="eyebrow">THE ROADMAP</span><h2>Course syllabus</h2>${['Starting with the essentials','Structures, systems & key ideas','From theory to scientific context','Review and knowledge check'].map((x,i)=>`<details ${i===0?'open':''}><summary><span class="module-num">0${i+1}</span><b>${x}</b><span class="module-meta">${i===3?'1':'3'} lessons <i>⌄</i></span></summary><div class="lesson-row"><span>▷</span>Introduction and learning goals <small>8 min</small></div><div class="lesson-row"><span>▤</span>Key concepts and guided notes <small>12 min</small></div></details>`).join('')}</div></section><aside class="course-aside"><div class="content-panel"><h3>Course at a glance</h3><div class="aside-row"><span>Difficulty</span><b>${c.level}</b></div><div class="aside-row"><span>Time to complete</span><b>${c.duration}</b></div><div class="aside-row"><span>Lessons</span><b>${c.lessons}</b></div><div class="aside-row"><span>Language</span><b>English</b></div><div class="aside-row"><span>Access</span><b class="free-label">Always free</b></div><p class="aside-disclaimer">This course is educational and does not offer university credit or professional licensure.</p></div></aside></div>`}
function dashboard(){let courses=state.enrolled.map(x=>courseData.find(c=>c.id===x)).filter(Boolean),avg=courses.length?Math.round(courses.reduce((a,c)=>a+(state.progress[c.id]||0),0)/courses.length):0;return `${header('YOUR LEARNING SPACE',`Welcome back, ${esc(state.user.name.split(' ')[0])}.`,'A little progress adds up. Here’s where your learning is today.',`<a class="btn btn-primary" href="#courses">Find a course <span>→</span></a>`)}<div class="dashboard-grid"><section class="dashboard-main"><div class="stats-grid"><div class="stat-card"><span class="stat-icon blue-icon">▤</span><small>COURSES ENROLLED</small><b>${courses.length.toString().padStart(2,'0')}</b><span class="stat-foot">Your learning journey</span></div><div class="stat-card"><span class="stat-icon green-icon">◷</span><small>OVERALL PROGRESS</small><b>${avg}<small>%</small></b><span class="stat-foot">Across enrolled courses</span></div><div class="stat-card"><span class="stat-icon purple-icon">✓</span><small>LESSONS COMPLETED</small><b>${courses.reduce((a,c)=>a+Math.round(c.lessons*(state.progress[c.id]||0)/100),0)}</b><span class="stat-foot">Keep the momentum</span></div></div><div class="panel progress-panel"><div class="panel-title"><div><span class="eyebrow">PICK UP WHERE YOU LEFT OFF</span><h2>Your courses</h2></div><a href="#courses">Browse all →</a></div>${courses.length?courses.map(c=>`<div class="continue-item"><div class="mini-course-art ${c.color}">${c.icon}</div><div class="continue-info"><span>${c.category} · ${c.level}</span><b>${c.title}</b><div class="progress-line"><i style="width:${state.progress[c.id]||0}%"></i></div><small>${state.progress[c.id]||0}% complete · ${c.lessons} lessons</small></div><a class="continue-button" href="#lesson/${c.id}" aria-label="Continue ${c.title}">→</a></div>`).join(''):`<div class="empty-state"><span>◉</span><h3>Your learning starts here</h3><p>Choose a free course and it will appear here.</p><a href="#courses" class="btn btn-primary">Explore courses →</a></div>`}</div><div class="panel activity-panel"><div class="panel-title"><div><span class="eyebrow">A GOOD RHYTHM</span><h2>Your learning activity</h2></div><span class="activity-legend"><i></i> Days you studied</span></div><div class="activity-chart">${Array.from({length:35},(_,i)=>`<i class="activity-day" title="${i%7===0?'A new week':''}" style="--level:${(i*7+3)%5}"></i>`).join('')}</div><div class="chart-labels"><span>5 weeks ago</span><span>THIS WEEK</span></div></div></section><aside class="dashboard-aside"><div class="profile-card"><div class="profile-avatar">${esc(state.user.name[0].toUpperCase())}</div><span class="eyebrow">YOUR PROFILE</span><h3>${esc(state.user.name)}</h3><p>${esc(state.user.role)} · Learning at your own pace</p><button class="btn btn-outline" id="editProfile">Edit profile <span>↗</span></button></div><div class="panel goal-card"><div class="goal-header"><span class="eyebrow">WEEKLY GOAL</span><span>✳</span></div><div class="goal-ring" style="--p:${Math.min(avg,100)}"><div><b>${avg}%</b><small>THIS WEEK</small></div></div><p>Every lesson brings you closer to the bigger picture.</p></div><div class="panel announcements"><span class="eyebrow">A NOTE FROM AM EDUCARE</span><h3>Stay curious.</h3><p>Our library and course collection is growing. Check back for new microbiology resources and topics to explore.</p><a href="#resources">See what's new <span>→</span></a></div></aside></div>`}
function lesson(id){let c=courseData.find(x=>x.id===id);if(!c)return detail(id);if(!state.enrolled.includes(id)){state.enrolled.push(id);save('am_enrolled',state.enrolled)}let p=state.progress[id]||0;return `<a class="back-link" href="#dashboard">← My learning</a><div class="lesson-layout"><section><div class="video-placeholder"><div class="video-glow"></div><button class="play-button" id="playVideo" aria-label="Play lesson">▷</button><span class="video-caption">A VISUAL INTRODUCTION</span><span class="video-note">LESSON 01 · 08:24</span></div><div class="lesson-heading"><div class="eyebrow">${c.category.toUpperCase()} · MODULE 01</div><h1>${c.title}: getting started</h1><p>A guided introduction to the core ideas behind this topic, with room to pause, reflect and revisit.</p><div class="lesson-controls"><button class="btn btn-outline" id="markLesson">${p>0?'✓ Lesson completed':'✓ Mark complete'}</button><a class="btn btn-primary" href="#lesson/${courseData[(courseData.indexOf(c)+1)%courseData.length].id}">Next lesson <span>→</span></a></div></div><div class="content-panel lesson-notes"><span class="eyebrow">YOUR STUDY NOTES</span><h2>Key ideas to remember</h2><p>Microbiology helps us explore the diversity of life at scales too small to see unaided. Start with careful observation, clear definitions and a willingness to ask what the evidence shows.</p><div class="note-banner"><span>✳</span><p>Learning resource: this introductory lesson is a conceptual overview. Follow your institution's guidance for practical laboratory work.</p></div></div></section><aside class="content-panel lesson-sidebar"><span class="eyebrow">COURSE CONTENT</span><h3>${c.title}</h3><div class="side-progress"><div><span>YOUR PROGRESS</span><b>${p}%</b></div><div class="progress-line"><i style="width:${p}%"></i></div></div>${['Welcome & learning goals','The core concepts','A closer look','Review & knowledge check'].map((l,i)=>`<a class="lesson-nav-item ${i===0?'current':''}" href="#lesson/${id}"><span>${i<p/25?'✓':'▷'}</span><div><b>${l}</b><small>${i===0?'Video lesson · 8 min':'Lesson · 12 min'}</small></div></a>`).join('')}</aside></div>`}
function resources(){let rs=[['✳','Concept glossary','A plain-language guide to essential microbiology terms.','GLOSSARY','blue'],['▧','Microbiology study guide','A structured outline for reviewing foundational concepts.','STUDY GUIDE','mint'],['⌕','Microscopy: a visual primer','An introduction to microscopy concepts and image interpretation.','VISUAL GUIDE','lavender'],['⌘','Molecular biology quick reference','A concise review of DNA, transcription and translation.','REFERENCE','peach'],['❋','Microbial ecology: field notes','Explore microbial communities across different habitats.','READING NOTES','green'],['⚗','Laboratory techniques overview','Understand key concepts in staining, media and identification.','LAB REFERENCE','yellow']];return `${header('THE STUDY LIBRARY','A little more to <em>explore.</em>','Study guides, glossaries and reference notes for curious microbiology learners.')}<div class="filter-bar"><label class="search-box"><span>⌕</span><input id="resourceSearch" placeholder="Find a resource…"></label><select id="resourceType"><option>All formats</option><option>Glossary</option><option>Study guide</option><option>Reference</option><option>Visual guide</option></select><span class="result-count">CURATED FOR LEARNING</span></div><div id="resourceGrid" class="resource-grid">${rs.map(r=>`<article class="resource-card" data-search="${r[1].toLowerCase()} ${r[3].toLowerCase()}"><div class="resource-art ${r[4]}"><span>${r[0]}</span><small>${r[3]}</small></div><div class="resource-content"><span class="eyebrow">${r[3]}</span><h3>${r[1]}</h3><p>${r[2]}</p><button class="resource-action" data-resource="${r[1]}">Open study resource <span>→</span></button></div></article>`).join('')}</div><div class="note-banner"><span>ⓘ</span><p>Resources are provided for educational purposes. Check individual publication terms before sharing third-party materials.</p></div>`}
const questions=[{q:'Which structure is the primary site of protein synthesis in a bacterial cell?',opts:['Ribosome','Golgi apparatus','Mitochondrion','Nuclear envelope'],answer:0,why:'Bacterial ribosomes translate messenger RNA into proteins. Bacteria lack membrane-bound organelles such as the Golgi apparatus and mitochondria.'},{q:'Which statement best describes a bacterial cell wall?',opts:['It is composed primarily of cellulose','It commonly contains peptidoglycan','It is always absent in bacteria','It stores the cell’s chromosomes'],answer:1,why:'Most bacterial cell walls contain peptidoglycan, a polymer that provides structural support. There are notable exceptions to this generalization.'},{q:'What does a Gram stain help distinguish?',opts:['Prokaryotes from eukaryotes','Two broad groups of bacteria with different cell-wall properties','Viruses from all other microorganisms','Living cells from dead cells'],answer:1,why:'The Gram stain separates bacteria based on differences in their cell-envelope structure and how they retain the crystal violet–iodine complex.'}];
function quiz(){return `${header('A MOMENT TO RECALL','Check what’s <em>sticking.</em>','Three quick questions. Learn from the explanations, and take them again any time.')}<div class="quiz-layout"><section class="quiz-card" id="quizCard"><div class="quiz-top"><span class="eyebrow">GENERAL MICROBIOLOGY · QUICK CHECK</span><span class="quiz-count" id="quizCount">QUESTION 01 OF 03</span></div><div class="quiz-meter"><i id="quizMeter"></i></div><div id="quizQuestion"></div></section><aside class="content-panel quiz-aside"><span class="quiz-light">✳</span><span class="eyebrow">LOW PRESSURE, HIGH CURIOSITY</span><h3>Learning is a process, not a score.</h3><p>Take your time, pick the answer that feels right, then use each explanation as a chance to learn something new.</p><div class="quiz-facts"><span>03 questions</span><span>About 2 minutes</span><span>Try as many times as you like</span></div></aside></div>`}
function renderQ(){let q=questions[quizI];document.querySelector('#quizQuestion').innerHTML=`<h2>${q.q}</h2><div class="answer-list">${q.opts.map((x,i)=>`<button class="answer-option" data-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${x}</button>`).join('')}</div><div id="answerFeedback"></div>`;document.querySelector('#quizCount').textContent=`QUESTION ${String(quizI+1).padStart(2,'0')} OF 03`;document.querySelector('#quizMeter').style.width=`${(quizI+1)/3*100}%`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer))}let quizI=0,quizScore=0;function answer(i){let q=questions[quizI],ok=i===q.answer;if(ok)quizScore++;document.querySelectorAll('[data-answer]').forEach((b,j)=>{b.disabled=true;if(j===q.answer)b.classList.add('correct');else if(j===i)b.classList.add('incorrect')});document.querySelector('#answerFeedback').innerHTML=`<div class="answer-feedback ${ok?'correct-text':'incorrect-text'}"><b>${ok?'That’s right. Nice work.':'Not quite — here’s the idea.'}</b><p>${q.why}</p><button class="btn btn-primary" id="nextQuestion">${quizI<2?'Next question':'See my result'} <span>→</span></button></div>`;document.querySelector('#nextQuestion').onclick=()=>{quizI++;if(quizI<3)renderQ();else{document.querySelector('#quizCard').innerHTML=`<div class="quiz-result"><span>✳</span><div class="eyebrow">QUICK CHECK COMPLETE</div><h2>${quizScore===3?'Excellent work.':quizScore?'Every question teaches you something.':'A solid first pass.'}</h2><p>You got ${quizScore} of 3 questions right. ${quizScore<3?'Revisit the explanations or take another pass when you’re ready.':'Keep following that curiosity.'}</p><button class="btn btn-primary" id="retryQuiz">Try again <span>↻</span></button></div>`;document.querySelector('#retryQuiz').onclick=()=>{quizI=0;quizScore=0;renderQ()}}}}
function community(){let p=state.posts;return `${header('THE MICROBIOLOGY COMMUNITY','Science gets better <em>shared.</em>','Ask a good question, share a study tip or join a thoughtful scientific conversation.',`<button class="btn btn-primary" id="newPost">Start a discussion <span>＋</span></button>`)}<div class="community-layout"><section class="discussion-list"><div class="discussion-filters"><b>Recent discussions</b><select id="discussionFilter"><option>All topics</option><option>Study questions</option><option>Lab concepts</option><option>Career paths</option></select></div>${[...p,...[{title:'What’s the clearest way to remember Gram-positive vs. Gram-negative?',body:'I keep mixing up how the cell wall relates to the staining result. Any memory aids that helped you?',author:'Ananya K.',topic:'Study questions',replies:4,stamp:'Today',id:'sample1'},{title:'Starting to explore microbial ecology — where should I begin?',body:'I’m interested in soil and water microbiology. Which foundational concepts are most useful?',author:'Samir P.',topic:'Study questions',replies:2,stamp:'Yesterday',id:'sample2'},{title:'Understanding microscopy resolution and magnification',body:'These terms sound similar but describe different things. What’s an intuitive way to distinguish them?',author:'Mira R.',topic:'Lab concepts',replies:7,stamp:'2 days ago',id:'sample3'}]].map((x,i)=>`<article class="discussion-card" data-topic="${x.topic||'Study questions'}"><div class="post-avatar post-color-${i%4}">${esc((x.author||state.user.name)[0])}</div><div class="post-main"><div class="post-meta"><span>${esc(x.topic||'Study questions')}</span><i>·</i><span>${esc(x.stamp||'Just now')}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.body)}</p><div class="post-footer"><span>◯ ${x.replies||0} replies</span><button data-like="${x.id}">♡ Helpful</button><button data-reply="${x.id}">Reply ↗</button></div></div></article>`).join('')}</section><aside class="community-aside"><div class="content-panel"><span class="eyebrow">OUR COMMUNITY GUIDELINES</span><h3>Curiosity thrives with care.</h3><ul><li>Discuss ideas with respect and kindness.</li><li>Share sources when you can.</li><li>Ask questions in a spirit of learning.</li><li>Keep conversations focused on science.</li></ul></div><div class="note-banner"><span>ⓘ</span><p>Community features on this preview are saved to this browser. A live, moderated forum needs a connected backend.</p></div></aside></div>`}
const opportunities=[['Research assistant, microbial ecology','University research group','Kolkata, India','Postgraduate students in microbiology or life sciences.','Rolling','Research'],['QC microbiology trainee','Biopharma and quality systems','Hyderabad, India','Life-science graduates with an interest in quality systems.','30 Nov 2026','Industry'],['Summer internship: environmental microbiology','Centre for environmental research','Pune, India','Undergraduate and postgraduate microbiology students.','15 Dec 2026','Internship'],['Laboratory technician, microbiology','Clinical diagnostics laboratory','Bengaluru, India','BSc in microbiology or an allied life science.','Applications open','Laboratory']];
function careers(){return `${header('YOUR NEXT CHAPTER','Where microbiology <em>can take you.</em>','Explore pathways, internships and research roles. Listings are examples; check each organization’s current criteria.',`<a class="btn btn-outline" href="#resources">MSc & PhD guidance <span>↗</span></a>`)}<div class="career-pills">${['All opportunities','Internships','Research','Laboratory','Industry'].map((x,i)=>`<button class="career-pill ${i===0?'active':''}" data-career="${x}">${x}</button>`).join('')}</div><div id="opportunityList">${opportunities.map((o,i)=>`<article class="opportunity-card" data-kind="${o[5]}"><div class="opportunity-icon">${['⌬','✓','✳','⌕'][i]}</div><div class="opportunity-main"><span class="eyebrow">${o[5].toUpperCase()}</span><h3>${o[0]}</h3><p>${o[1]} <span>·</span> ${o[2]}</p><small>${o[3]}</small></div><div class="opportunity-deadline"><small>APPLICATION DEADLINE</small><b>${o[4]}</b></div><button class="icon-link" data-opportunity="${i}" aria-label="View opportunity">↗</button></article>`).join('')}</div><div class="note-banner"><span>ⓘ</span><p>Opportunities are illustrative listings for this preview. Please verify current availability and eligibility directly with the organization.</p></div>`}
function about(){return `${header('OUR PURPOSE','Learn microbiology.<br><em>Understand life.</em>','AM Educare is a free learning space dedicated to the small science with a big impact.')}<div class="about-grid"><div class="about-visual"><div class="cell-orbit orbit-a"></div><div class="cell-body large-cell"><span class="cell-core"></span><i class="cell-dot d1"></i><i class="cell-dot d2"></i><i class="cell-dot d3"></i><i class="cell-dot d4"></i></div><span class="visual-note note-a">AM EDUCARE · EST. FOR THE CURIOUS</span></div><div class="about-copy"><span class="eyebrow">WHY WE'RE HERE</span><h2>Good science learning should be <em>within reach.</em></h2><p>Microorganisms shape our health, our food, our ecosystems and our future. AM Educare brings together approachable courses, study materials and scientific conversations so learners can explore that world with confidence.</p><p>Our focus is microbiology and its connected disciplines, from immunology and molecular biology to biotechnology and environmental science.</p><div class="mission-quote">“Making quality Microbiology education accessible to everyone.”</div></div></div><div class="values-grid">${[['01','Free by design','Every AM Educare course is free to access. Learning should be open to everyone.'],['02','Science with care','We value evidence, clear explanations and honesty about what is still uncertain.'],['03','Built for learners','Start where you are. Learn at your own pace. Follow the questions that matter to you.']].map(x=>`<article><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div><div class="note-banner"><span>ⓘ</span><p>AM Educare course completion certificates recognize participation in learning activities and do not represent university accreditation, academic credit or professional licensing.</p></div>`}
function faq(){return `${header('GOOD QUESTIONS','A few things you <em>might be wondering.</em>','A little context before you begin exploring.')}<div class="faq-list">${[['Are the courses really free?','Yes. Every course in the AM Educare learning catalogue is free.'],['Who are the courses for?','Undergraduate and postgraduate students, researchers, laboratory professionals and anyone curious about microbiology. Course levels are listed so you can find a comfortable starting point.'],['Will I receive a certificate?','A course completion certificate may be available as a record of learning. It does not confer academic credit, university accreditation or professional licensure.'],['Can I use these materials for laboratory work?','Learning materials explain concepts. They are not protocols for unsupervised experiments; follow qualified supervision, institutional policies and appropriate safety guidance for practical laboratory work.'],['Does this preview save my learning?','This browser preview keeps demo account, enrollment and progress data in local storage on your device. A real service requires a configured secure backend.'],['Are AM Educare job listings verified?','Listings in this preview are illustrative. Always verify the opportunity, eligibility and application deadline with the organization.']].map((x,i)=>`<details ${i===0?'open':''}><summary>${x[0]}<span>＋</span></summary><p>${x[1]}</p></details>`).join('')}</div>`}
function authPage(register){return `<div class="auth-wrap"><div class="auth-card"><div class="auth-brand"><span class="brand-mark">A<span>m</span></span><span>AM Educare</span></div><div class="eyebrow">YOUR LEARNING JOURNEY STARTS HERE</div><h1>${register?'Create your account.':'Welcome back.'}</h1><p>${register?'Join a growing community of curious microbiology learners.':'Pick up where your microbiology learning left off.'}</p><form id="authForm">${register?'<label>Your name<input name="name" required minlength="2" placeholder="e.g. Aisha Rahman"></label>':''}<label>Email address<input type="email" name="email" required placeholder="you@example.com"></label><label>Password<input type="password" name="password" required minlength="6" placeholder="At least 6 characters"></label><button class="btn btn-primary auth-submit">${register?'Create free account':'Sign in'} <span>→</span></button></form><div class="auth-terms">${register?'By creating an account, you agree to our educational-use guidelines.':'Your learning space is ready when you are.'}</div><div class="auth-switch">${register?'Already learning with us?':'New to AM Educare?'} <a href="#${register?'login':'register'}">${register?'Sign in':'Create a free account'}</a></div><div class="demo-note">Preview account: this form creates a local demo session on this device. Secure sign-in and Google authentication are not configured in this static preview.</div></div></div>`}
function contact(){return `${header('GET IN TOUCH','We’re listening. <em>Get in touch.</em>','A question about learning or a thought about the platform? Send a note.')}<div class="contact-layout"><form id="contactForm" class="content-panel contact-form"><label>Your name<input name="name" required placeholder="Your name"></label><label>Email address<input type="email" name="email" required placeholder="you@example.com"></label><label>What would you like to share?<textarea name="message" rows="5" minlength="10" required placeholder="Write your message here…"></textarea></label><button class="btn btn-primary">Send message <span>→</span></button><p class="demo-note">Messages are not sent in this static preview.</p></form><div class="contact-note"><span class="eyebrow">A PLATFORM FOR THE SCIENTIFICALLY CURIOUS</span><h2>Let’s make space for <em>better questions.</em></h2><p>AM Educare is here to help microbiology learners find a path, follow an idea and build a stronger understanding of the living world.</p><a class="arrow-link" href="#courses">Explore the course catalogue ↗</a></div></div><div class="faq-list">${[['Where should I start?','Try A World of Microbes for a friendly introduction, or explore a course that connects to a subject you already enjoy.'],['How do I suggest a topic?','Use the contact form to share the question or learning resource you think would help the community.']].map(x=>`<details><summary>${x[0]}<span>＋</span></summary><p>${x[1]}</p></details>`).join('')}</div>`}
function legal(type){let title=type==='privacy'?'Privacy & data':'Terms of learning';return `${header('THE IMPORTANT DETAILS',`${title} <em>at AM Educare.</em>`,'Clear information about this learning platform and your experience.')}<div class="legal-copy"><div class="note-banner"><span>ⓘ</span><p>This demo site stores only locally entered learning data in your browser. It does not send or store account data on a server.</p></div><h2>${type==='privacy'?'Your information':'Learning with care'}</h2><p>${type==='privacy'?'In this static preview, enrollment, profile, bookmark, community and progress data are stored in local browser storage on your device. Clearing site data removes this information. No authentication service or server analytics are connected.':'AM Educare offers educational content for learning and general scientific understanding. Course completion certificates recognize learning activity only; they do not award academic credit, university accreditation or professional licensing.'}</p><h2>Educational context</h2><p>Content is provided for microbiology education. It is not clinical, medical, legal, professional or laboratory safety advice. Refer to qualified educators, authoritative sources and institutional guidance where appropriate.</p><h2>Resources and opportunities</h2><p>External opportunities and study resources should be independently checked for accuracy, licensing, current status and eligibility before use.</p><h2>Questions</h2><p>For platform questions, visit <a href="#contact">Contact Us</a>.</p><p class="legal-updated">Last updated: 17 November 2026</p></div>`}
function admin(){let tab=location.hash.split('/')[1]||'overview';let links=[['overview','◫','Overview'],['students','♙','Students'],['courses','▤','Courses'],['instructors','♧','Instructors'],['academic','✓','Academic'],['content','▧','Site content'],['analytics','⌁','Analytics']];let content=tab==='students'?`<div class="content-panel admin-panel"><div class="panel-title"><div><span class="eyebrow">LEARNER ACCOUNTS</span><h2>Student directory</h2></div><input id="studentSearch" class="admin-search" placeholder="Search students…"></div><div class="admin-table"><div class="table-head"><span>STUDENT</span><span>ROLE</span><span>ENROLMENTS</span><span>STATUS</span><span>ACTION</span></div><div id="studentRows">${[['Aisha Rahman','Student','3','Active'],['Rohan Sen','Student','2','Active'],['Mira Das','Student','1','Active'],['Samira Khan','Student','4','Active']].map(s=>`<div class="table-row"><b>${s[0]}</b><span>${s[1]}</span><span>${s[2]}</span><span class="published-tag">${s[3]}</span><button class="table-action" data-student="${s[0]}">View ↗</button></div>`).join('')}</div></div></div><div class="admin-notice">Student records here are sample rows. Connect Supabase and apply the migration to manage real accounts.</div>`:tab==='courses'?`<div class="content-panel admin-panel"><div class="panel-title"><div><span class="eyebrow">ACADEMIC CONTENT</span><h2>Course catalogue</h2></div><button id="addCourse" class="btn btn-primary">＋ Create course</button></div><div class="admin-table"><div class="table-head"><span>COURSE</span><span>SUBJECT</span><span>LEVEL</span><span>STATUS</span><span>ACTION</span></div>${courseData.map(c=>`<div class="table-row"><b>${c.title}</b><span>${c.category}</span><span>${c.level}</span><span class="published-tag">Published</span><button class="table-action" data-edit="${c.id}">Edit ↗</button></div>`).join('')}</div></div>`:tab==='instructors'?`<div class="instructor-grid">${[['Dr. Asha Menon','Cell Biology','Verified'],['Dr. Rohan Das','Immunology','Verified'],['Prof. Neel Chatterjee','Medical Microbiology','Review pending']].map((s,i)=>`<div class="content-panel instructor-admin"><span class="teacher-avatar">${s[0][4]}</span><span class="eyebrow">${s[1]}</span><h3>${s[0]}</h3><p>${s[2]}</p><button class="btn btn-outline" data-instructor="${s[0]}">Manage permissions</button></div>`).join('')}</div>`:tab==='academic'?`<div class="content-panel admin-panel"><span class="eyebrow">ACADEMIC OPERATIONS</span><h2>Assessments & submissions</h2><div class="admin-action-grid">${[['Create quiz','Build an assessment from a question bank.','＋'],['Review submissions','Grade work and provide instructor feedback.','↗'],['Certificates','Issue and verify course completion records.','✓'],['Live classes','Schedule an instructor session.','◷']].map(x=>`<button class="admin-action-card" data-admin-action="${x[0]}"><b>${x[2]}</b><strong>${x[0]}</strong><small>${x[1]}</small></button>`).join('')}</div></div>`:tab==='content'?`<div class="content-panel admin-panel"><div class="panel-title"><div><span class="eyebrow">SITE DISCOVERY</span><h2>Subject areas</h2></div><button id="addCategory" class="btn btn-outline">＋ Add subject</button></div><div class="admin-categories">${cats.map(c=>`<span>${c}<i>✓</i></span>`).join('')}</div><div class="admin-action-grid">${[['Announcements','Share updates with learners.','✳'],['Resources','Curate licensed study materials.','▧'],['Career listings','Publish and expire opportunities.','↗']].map(x=>`<button class="admin-action-card" data-admin-action="${x[0]}"><b>${x[2]}</b><strong>${x[0]}</strong><small>${x[1]}</small></button>`).join('')}</div></div>`:tab==='analytics'?`<div class="content-panel admin-panel"><span class="eyebrow">LEARNING INSIGHTS</span><h2>Platform analytics</h2><div class="admin-stats"><div><small>REGISTERED LEARNERS</small><b>1,248</b><span>Sample preview metric</span></div><div><small>COURSE COMPLETION</small><b>68%</b><span>Sample preview metric</span></div><div><small>QUIZ ATTEMPTS</small><b>3,806</b><span>Sample preview metric</span></div></div><div class="admin-chart">${Array.from({length:12},(_,i)=>`<i style="--h:${25+(i*31)%65}%"><span>${['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'][i]}</span></i>`).join('')}</div></div>`:`<div class="admin-notice">✳ You’re viewing preview data. Real student records and platform analytics will appear after you connect the database.</div><div class="admin-stats"><div><small>REGISTERED LEARNERS</small><b>1,248</b><span>Sample preview data</span></div><div><small>COURSE ENROLMENTS</small><b>${state.enrolled.length}</b><span>On this device</span></div><div><small>COMPLETION RATE</small><b>68%</b><span>Sample preview data</span></div></div><div class="admin-overview-grid"><div class="content-panel admin-panel"><div class="panel-title"><div><span class="eyebrow">CONTENT MANAGEMENT</span><h2>Manage courses</h2></div><a class="arrow-link" href="#admin/courses">View all →</a></div><div class="admin-course-list">${courseData.slice(0,4).map(c=>`<div><span class="mini-course-art ${c.color}">${c.icon}</span><b>${c.title}</b><small>${c.category}</small><a href="#course/${c.id}">↗</a></div>`).join('')}</div></div><div class="content-panel admin-panel"><span class="eyebrow">QUICK ACTIONS</span><h2>Keep learning moving.</h2><div class="admin-quick-actions"><a href="#admin/courses">＋ Create a course</a><a href="#admin/students">♙ Find a student</a><a href="#admin/academic">✓ Review assignments</a><a href="#admin/content">▧ Add a resource</a></div><div class="admin-microbe">◉</div></div></div>`;return `<div class="admin-shell"><aside class="admin-nav"><div class="eyebrow">AM EDUCARE</div><h2>Admin studio</h2><small>PLATFORM MANAGEMENT</small><nav>${links.map(x=>`<a class="${tab===x[0]?'active':''}" href="#admin/${x[0]}"><span>${x[1]}</span>${x[2]}</a>`).join('')}</nav><a href="#dashboard" class="admin-return">↗ Learner view</a></aside><section class="admin-workspace">${header(`ADMIN STUDIO · ${links.find(x=>x[0]===tab)?.[2].toUpperCase()||'OVERVIEW'}`,tab==='overview'?'A healthy learning <em>ecosystem.</em>':`${links.find(x=>x[0]===tab)?.[2]||'Admin'} <em>management.</em>`,'Thoughtful tools for building a better microbiology learning space.')}${content}</section></div>`}
function instructorPanel(){let tab=location.hash.split('/')[1]||'overview';const tabs=[['overview','Overview'],['courses','My courses'],['students','Learners'],['submissions','Assignments'],['classes','Live classes']];let body=tab==='courses'?`<div class="content-panel admin-panel"><div class="panel-title"><div><span class="eyebrow">YOUR TEACHING LIBRARY</span><h2>Courses you teach</h2></div><button class="btn btn-primary" data-admin-action="Create instructor course">＋ Create course</button></div><div class="admin-course-list">${courseData.slice(0,3).map(c=>`<div><span class="mini-course-art ${c.color}">${c.icon}</span><b>${c.title}</b><small>${c.lessons} lessons</small><a href="#course/${c.id}">↗</a></div>`).join('')}</div></div>`:tab==='students'?`<div class="content-panel admin-panel"><span class="eyebrow">LEARNER ENGAGEMENT</span><h2>Students in your courses</h2><div class="admin-notice">Connect Supabase to view enrolled learners and their course progress.</div><div class="empty-state"><span>◉</span><h3>Your learner list will appear here</h3><p>Enrollments will be visible once course data is connected.</p></div></div>`:tab==='submissions'?`<div class="content-panel admin-panel"><span class="eyebrow">ASSESSMENT REVIEW</span><h2>Assignment submissions</h2><div class="admin-notice">Submissions are stored in private file storage after setup. No student uploads are available in this preview.</div><div class="admin-action-grid"><button class="admin-action-card" data-admin-action="Review submissions"><b>▤</b><strong>Review queue</strong><small>Open and grade learner submissions.</small></button><button class="admin-action-card" data-admin-action="Assignment feedback"><b>✎</b><strong>Feedback</strong><small>Return grades and instructor notes.</small></button></div></div>`:tab==='classes'?`<div class="content-panel admin-panel"><div class="panel-title"><div><span class="eyebrow">SYNCHRONOUS LEARNING</span><h2>Live teaching sessions</h2></div><button class="btn btn-primary" data-admin-action="Schedule live class">＋ Schedule class</button></div><div class="empty-state"><span>◷</span><h3>No sessions scheduled</h3><p>Connect a meeting provider to create secure class sessions.</p></div></div>`:`<div class="admin-notice">Instructor tools are a role-specific preview. Course edits, learner records and assessment reviews require verified instructor permissions in Supabase.</div><div class="admin-stats"><div><small>MY COURSES</small><b>03</b><span>Preview teaching content</span></div><div><small>ENROLLED LEARNERS</small><b>186</b><span>Sample preview count</span></div><div><small>TO REVIEW</small><b>08</b><span>Sample pending work</span></div></div><div class="admin-overview-grid"><div class="content-panel admin-panel"><div class="panel-title"><div><span class="eyebrow">TEACHING</span><h2>Recent courses</h2></div><a class="arrow-link" href="#instructor-panel/courses">View courses →</a></div><div class="admin-course-list">${courseData.slice(0,3).map(c=>`<div><span class="mini-course-art ${c.color}">${c.icon}</span><b>${c.title}</b><small>${c.lessons} lessons</small><a href="#course/${c.id}">↗</a></div>`).join('')}</div></div><div class="content-panel admin-panel"><span class="eyebrow">NEXT UP</span><h2>Teaching checklist</h2><div class="admin-quick-actions"><a href="#instructor-panel/courses">▤ Review course materials</a><a href="#instructor-panel/submissions">✓ Grade assignments</a><a href="#instructor-panel/classes">◷ Plan a live class</a><a href="#instructor-panel/students">♙ Check learner progress</a></div></div></div>`;return `<div class="admin-shell instructor-shell"><aside class="admin-nav instructor-nav"><div class="eyebrow">AM EDUCARE</div><h2>Instructor space</h2><small>TEACHING WORKSPACE</small><nav>${tabs.map(x=>`<a class="${tab===x[0]?'active':''}" href="#instructor-panel/${x[0]}"><span>${['◫','▤','♙','✓','◷'][tabs.indexOf(x)]}</span>${x[1]}</a>`).join('')}</nav><a href="#dashboard" class="admin-return">↗ Student view</a></aside><section class="admin-workspace">${header(`INSTRUCTOR SPACE · ${tabs.find(x=>x[0]===tab)?.[1].toUpperCase()||'OVERVIEW'}`,tab==='overview'?'Make the science <em>come alive.</em>':`${tabs.find(x=>x[0]===tab)?.[1]||'Teaching'} <em>workspace.</em>`,'Thoughtful teaching tools for microbiology educators.')}${body}</section></div>`}
function instructors(){return `${header('MEET THE INSTRUCTORS','Learn from people who <em>love the science.</em>','Our instructors make core microbiology ideas feel clear, connected and worth exploring.')}<div class="instructor-grid">${[['Dr. Asha Menon','Microbial cell biology & foundations','PhD, Microbiology','A teacher and researcher who loves making the structure and function of microbial life click.','mint','A'],['Dr. Rohan Das','Immunology & laboratory concepts','PhD, Immunology','Interested in how immune systems recognize microbes and how scientific concepts come alive in the lab.','lavender','R'],['Prof. Neel Chatterjee','Molecular biology & medical microbiology','MSc, PhD, Life Sciences','Explores the connections between molecular mechanisms, microbial genetics and human health.','peach','N'],['Dr. Farah Khan','Environmental & industrial microbiology','PhD, Environmental Microbiology','Studies the vital work microorganisms do across natural ecosystems and applied science.','green','F']].map(x=>`<article class="instructor-card"><div class="instructor-art ${x[4]}"><div>${x[5]}</div><span class="instructor-orbit"></span><small>AM EDUCARE · INSTRUCTOR</small></div><div class="instructor-body"><span class="eyebrow">${x[1].toUpperCase()}</span><h3>${x[0]}</h3><b>${x[2]}</b><p>${x[3]}</p><a href="#courses">Explore their courses <span>→</span></a></div></article>`).join('')}</div><div class="note-banner"><span>ⓘ</span><p>Instructor profiles shown are representative educator profiles for this interface preview.</p></div>`}
function route(){let r=location.hash.slice(1)||'home',bits=r.split('/'),name=({home:'Overview',courses:'Explore courses',course:'Course details',dashboard:'Student panel',lesson:'Course lesson',resources:'Study library',quiz:'Quick quiz',community:'Community',careers:'Careers & internships',about:'About AM Educare',faq:'Frequently asked questions',login:'Sign in',register:'Create an account',contact:'Contact AM Educare',privacy:'Privacy & data',terms:'Terms of learning',admin:'Admin studio', 'instructor-panel':'Instructor panel',instructors:'Instructor directory'})[bits[0]]||'Overview';document.querySelector('#currentPage').textContent=name;document.querySelectorAll('.side-nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===bits[0]||(bits[0]==='course'&&a.dataset.route==='courses')));document.querySelector('#userName').textContent=state.user.name;document.querySelector('#userRole').textContent=state.user.role;document.querySelector('#topAvatar').textContent=state.user.name[0].toUpperCase();let views={home,courses:courseList,dashboard,resources,quiz,community,careers,about,faq,login:()=>authPage(false),register:()=>authPage(true),contact,privacy:()=>legal('privacy'),terms:()=>legal('terms'),admin,instructors,'instructor-panel':instructorPanel};app.innerHTML=bits[0]==='course'?detail(bits[1]):bits[0]==='lesson'?lesson(bits[1]):(views[bits[0]]||home)();window.scrollTo(0,0);bindRoute();}
function openModal(s){modalContent.innerHTML=s;modal.showModal()}
function bindRoute(){document.querySelector('#courseSearch')?.addEventListener('input',e=>{state.query=e.target.value;let pos=e.target.selectionStart;document.querySelector('.course-grid').innerHTML=filteredCourses();let el=document.querySelector('#courseSearch');el.value=state.query;el.focus();el.setSelectionRange(pos,pos);bindCards()});document.querySelector('#categoryFilter')?.addEventListener('change',e=>{state.category=e.target.value;route()});document.querySelector('#levelFilter')?.addEventListener('change',e=>{state.level=e.target.value;route()});document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{state.category=state.category===b.dataset.cat?'All subjects':b.dataset.cat;route()});bindCards();document.querySelectorAll('[data-enroll]').forEach(b=>b.onclick=()=>{if(!state.enrolled.includes(b.dataset.enroll))state.enrolled.push(b.dataset.enroll);save('am_enrolled',state.enrolled);state.progress[b.dataset.enroll]=state.progress[b.dataset.enroll]||0;save('am_progress',state.progress);toast('You’re enrolled. Your learning journey starts now.');route()});document.querySelector('#authForm')?.addEventListener('submit',e=>{e.preventDefault();let d=new FormData(e.currentTarget);state.user={name:d.get('name')||d.get('email').split('@')[0],role:'Student'};save('am_user',state.user);toast('Welcome to AM Educare.');location.hash='#dashboard'});document.querySelector('#markLesson')?.addEventListener('click',()=>{let id=location.hash.split('/')[1];state.progress[id]=Math.min(100,(state.progress[id]||0)+25);save('am_progress',state.progress);toast('Lesson progress saved on this device.');route()});document.querySelector('#playVideo')?.addEventListener('click',()=>toast('Video streaming will be available when a video provider is configured.'));document.querySelector('#editProfile')?.addEventListener('click',()=>openModal(`<span class="eyebrow">YOUR LEARNING PROFILE</span><h2>Edit your profile</h2><form id="profileForm"><label>Display name<input name="name" required minlength="2" value="${esc(state.user.name)}"></label><button class="btn btn-primary">Save profile</button></form>`));document.querySelector('#profileForm')?.addEventListener('submit',e=>{e.preventDefault();state.user.name=new FormData(e.currentTarget).get('name');save('am_user',state.user);modal.close();route();toast('Your profile was updated.')});document.querySelector('#resourceSearch')?.addEventListener('input',filterResources);document.querySelector('#resourceType')?.addEventListener('change',filterResources);document.querySelectorAll('[data-resource]').forEach(b=>b.onclick=()=>openModal(`<span class="eyebrow">AM EDUCARE · STUDY RESOURCE</span><h2>${esc(b.dataset.resource)}</h2><p class="resource-modal-intro">A clear, approachable starting point for your microbiology revision.</p><h3>Keep in mind</h3><p>Scientific concepts connect across subjects. Start by defining unfamiliar terms, then use the course catalogue and recommended reading to follow ideas further.</p><p>For in-depth study, consult your course materials and trusted academic references. This resource is an educational overview, not laboratory instructions.</p><button class="btn btn-primary" onclick="document.querySelector('#modal').close()">Done <span>✓</span></button>`));document.querySelector('#newPost')?.addEventListener('click',()=>openModal(`<span class="eyebrow">START A SCIENTIFIC CONVERSATION</span><h2>What’s on your mind?</h2><form id="postForm"><label>Topic<select name="topic"><option>Study questions</option><option>Lab concepts</option><option>Career paths</option></select></label><label>Your question or idea<input name="title" minlength="8" required placeholder="A clear, thoughtful headline"></label><label>More context<textarea name="body" minlength="10" required rows="4" placeholder="Share the details…"></textarea></label><button class="btn btn-primary">Post discussion <span>→</span></button></form><p class="demo-note">Your discussion will be saved locally in this browser preview.</p>`));document.querySelector('#postForm')?.addEventListener('submit',e=>{e.preventDefault();let d=new FormData(e.currentTarget);state.posts.unshift({id:Date.now(),author:state.user.name,stamp:'Just now',replies:0,title:d.get('title'),body:d.get('body'),topic:d.get('topic')});save('am_posts',state.posts);modal.close();route();toast('Your discussion was posted.')});document.querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>toast('Thanks for supporting scientific discussion.'));document.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>openModal(`<span class="eyebrow">JOIN THE CONVERSATION</span><h2>Share a helpful reply.</h2><form id="replyForm"><label>Your reply<textarea name="reply" required minlength="5" rows="4" placeholder="Add a thoughtful response…"></textarea></label><button class="btn btn-primary">Submit reply <span>→</span></button></form><p class="demo-note">Replies are for demonstration in this local preview.</p>`));document.querySelector('#replyForm')?.addEventListener('submit',e=>{e.preventDefault();modal.close();toast('Thanks for contributing to the discussion.')});document.querySelectorAll('[data-career]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-career]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.opportunity-card').forEach(x=>x.hidden=b.dataset.career!=='All opportunities'&&x.dataset.kind.toLowerCase()!==b.dataset.career.replace(/s$/,'').toLowerCase())});document.querySelectorAll('[data-opportunity]').forEach(b=>b.onclick=()=>{let o=opportunities[+b.dataset.opportunity];openModal(`<span class="eyebrow">${o[5].toUpperCase()} · SAMPLE LISTING</span><h2>${o[0]}</h2><p>${o[1]} · ${o[2]}</p><h3>Eligibility</h3><p>${o[3]}</p><p><b>Application deadline:</b> ${o[4]}</p><p class="demo-note">This is an illustrative opportunity. Confirm current openings directly with the organization.</p><button class="btn btn-primary" onclick="document.querySelector('#modal').close()">Close</button>`)});document.querySelector('#contactForm')?.addEventListener('submit',e=>{e.preventDefault();toast('Thanks for your message. Sending is not configured in this preview.');e.currentTarget.reset()});document.querySelector('#addCourse')?.addEventListener('click',()=>openModal('<span class="eyebrow">COURSE MANAGEMENT · DEMO</span><h2>Add a course</h2><form id="addCourseForm"><label>Course title<input name="title" required></label><label>Subject<input name="category" required></label><label>Short description<textarea name="desc" required minlength="10"></textarea></label><label>Level<select name="level"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></label><button class="btn btn-primary">Add to preview catalogue</button></form>'));document.querySelector('#addCourseForm')?.addEventListener('submit',e=>{e.preventDefault();let d=new FormData(e.currentTarget);courseData.push({id:'new-'+Date.now(),title:d.get('title'),category:d.get('category'),desc:d.get('desc'),level:d.get('level'),duration:'3 hours',lessons:5,instructor:state.user.name,tag:'NEW COURSE',color:'mint',icon:'✳'});modal.close();route();toast('Course added to this preview.')});document.querySelector('#addCategory')?.addEventListener('click',()=>openModal('<span class="eyebrow">COURSE MANAGEMENT · DEMO</span><h2>Add a subject area</h2><form id="addCatForm"><label>Subject name<input name="cat" required></label><button class="btn btn-primary">Add subject</button></form>'));document.querySelector('#addCatForm')?.addEventListener('submit',e=>{e.preventDefault();cats.push(new FormData(e.currentTarget).get('cat'));modal.close();route();toast('Subject added to this preview.')});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{let c=courseData.find(x=>x.id===b.dataset.edit);location.hash=`#course/${c.id}`});}
function filteredCourses(){return courseData.filter(c=>(state.category==='All subjects'||c.category===state.category)&&(state.level==='All levels'||c.level===state.level)&&`${c.title} ${c.desc} ${c.category}`.toLowerCase().includes(state.query.toLowerCase())).map(courseCard).join('')||'<div class="empty-state"><span>⌕</span><h3>No courses found yet</h3><p>Try a different search or subject.</p></div>'}
function bindCards(){document.querySelectorAll('[data-bookmark]').forEach(b=>b.onclick=()=>{let id=b.dataset.bookmark;if(state.bookmarks.includes(id))state.bookmarks=state.bookmarks.filter(x=>x!==id);else state.bookmarks.push(id);save('am_bookmarks',state.bookmarks);b.classList.toggle('saved');b.textContent=state.bookmarks.includes(id)?'♥':'♡';toast(state.bookmarks.includes(id)?'Added to your saved courses.':'Removed from saved courses.')})}
function filterResources(){let q=(document.querySelector('#resourceSearch')?.value||'').toLowerCase(),type=(document.querySelector('#resourceType')?.value||'All formats').toLowerCase();document.querySelectorAll('.resource-card').forEach(x=>x.hidden=!x.dataset.search.includes(q)||(type!=='all formats'&&!x.dataset.search.includes(type)))}
document.querySelector('#modalClose').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});document.querySelector('#menuButton').onclick=()=>document.querySelector('#sidebar').classList.toggle('sidebar-open');document.querySelectorAll('.side-nav a').forEach(a=>a.onclick=()=>document.querySelector('#sidebar').classList.remove('sidebar-open'));document.querySelector('#profileButton').onclick=()=>location.hash='#dashboard';document.querySelector('#notifyButton').onclick=()=>toast('You’re all caught up.');window.addEventListener('hashchange',()=>{route();document.querySelector('#sidebar').classList.remove('sidebar-open')});window.addEventListener('keydown',e=>{if(e.key==='Escape')modal.close()});route();if(location.hash==='#quiz'){renderQ()}
window.addEventListener('hashchange',()=>{if(location.hash==='#quiz')renderQ()});
function addStudentTabs(){if(!location.hash.startsWith('#dashboard'))return;const h=app.querySelector('.page-heading');if(!h||app.querySelector('.student-tabs'))return;h.insertAdjacentHTML('afterend',`<nav class="student-tabs" aria-label="Student panel sections">${[['dashboard','Overview'],['dashboard/courses','My courses'],['dashboard/saved','Saved courses'],['dashboard/certificates','Certificates']].map(t=>`<a class="${location.hash==='#'+t[0]?'active':''}" href="#${t[0]}">${t[1]}</a>`).join('')}</nav>`)}
addStudentTabs();window.addEventListener('hashchange',()=>setTimeout(addStudentTabs,0));
document.addEventListener('input',e=>{if(e.target.id==='studentSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('#studentRows .table-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))}});
document.addEventListener('click',e=>{const student=e.target.closest('[data-student]');if(student)openModal(`<span class="eyebrow">LEARNER ACCOUNT · SAMPLE DATA</span><h2>${esc(student.dataset.student)}</h2><p>Enrolled courses and learning activity are available to authorized administrators after the database is connected.</p><div class="admin-notice">Sample preview profile. No real student records are being accessed.</div><button class="btn btn-outline" onclick="document.querySelector('#modal').close()">Close</button>`);const instructor=e.target.closest('[data-instructor]');if(instructor)toast('Instructor permission controls require the connected administrator service.');const action=e.target.closest('[data-admin-action]');if(action)toast(`${action.dataset.adminAction}: connect Supabase to enable this admin operation.`)});

